import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.Cx5sLWzU.js";const u=JSON.parse('{"title":"转义序列（概要）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/escape-sequences.md","filePath":"guide/escape-sequences.md","lastUpdated":1792695761000}'),r={name:"guide/escape-sequences.md"};function c(s,e,i,l,n,h){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="转义序列-概要" tabindex="-1">转义序列（概要） <a class="header-anchor" href="#转义序列-概要" aria-label="Permalink to &quot;转义序列（概要）&quot;">​</a></h1><p>本章仅作<strong>实用概要</strong>，便于理解 TUI、标题栏与 Shell 集成行为。完整、持续更新的说明见官方：</p><ul><li><a href="https://wezterm.org/escape-sequences.html" target="_blank" rel="noreferrer">Escape Sequences</a></li></ul><div class="info custom-block"><p class="custom-block-title">文档性质</p><p>官方明确指出该页是「活文档」，可能与某一稳定版不完全同步。实现细节以你安装的版本与官方页面为准。</p></div><h2 id="编码前提" tabindex="-1">编码前提 <a class="header-anchor" href="#编码前提" aria-label="Permalink to &quot;编码前提&quot;">​</a></h2><p>WezTerm 将终端输出视为 <strong>UTF-8</strong> 码点流，不支持其它字符编码。C1 控制码的 8 位形式仅在按 Unicode 码点经 UTF-8 多字节编码后才会被识别；直接发送原始 8 位二进制通常不符合预期。日常优先使用 7 位 <code>ESC ...</code> 形式。</p><h2 id="与日常相关的几类序列" tabindex="-1">与日常相关的几类序列 <a class="header-anchor" href="#与日常相关的几类序列" aria-label="Permalink to &quot;与日常相关的几类序列&quot;">​</a></h2><h3 id="osc-操作系统命令-标题、目录、通知等" tabindex="-1">OSC：操作系统命令（标题、目录、通知等） <a class="header-anchor" href="#osc-操作系统命令-标题、目录、通知等" aria-label="Permalink to &quot;OSC：操作系统命令（标题、目录、通知等）&quot;">​</a></h3><p>OSC 以 <code>ESC ]</code> 开始，参数常用 <code>;</code> 分隔，以 <code>ST</code>（<code>ESC \\</code>）结束；WezTerm 也接受以 <code>BEL</code>（<code>0x07</code>）结尾。</p><table tabindex="0"><thead><tr><th>OSC</th><th>作用（摘自官方表）</th><th>示例</th></tr></thead><tbody><tr><td><code>0</code></td><td>设置窗口标题，并<strong>清空</strong>图标名</td><td><code>\\x1b]0;title\\x1b\\\\</code></td></tr><tr><td><code>1</code></td><td>设置图标名；非空时用作<strong>标签标题</strong></td><td><code>\\x1b]1;tab-title\\x1b\\\\</code></td></tr><tr><td><code>2</code></td><td>设置窗口标题</td><td><code>\\x1b]2;window-title\\x1b\\\\</code></td></tr><tr><td><code>4</code></td><td>设置 / 查询调色板 0–255 号颜色</td><td><code>\\x1b]4;2;#cccccc\\x1b\\\\</code></td></tr><tr><td><code>7</code></td><td>设置当前工作目录（Shell 集成）</td><td>见 <a href="https://wezterm.org/shell-integration.html" target="_blank" rel="noreferrer">Shell Integration</a></td></tr><tr><td><code>8</code></td><td>显式超链接</td><td>见 <a href="https://wezterm.org/hyperlinks.html" target="_blank" rel="noreferrer">hyperlinks</a></td></tr><tr><td><code>9</code></td><td>显示系统 toast 通知（iTerm2 风格）</td><td><code>printf &quot;\\e]9;%s\\e\\\\&quot; &quot;hello&quot;</code></td></tr><tr><td><code>10</code> / <code>11</code> / <code>12</code></td><td>默认前景 / 默认背景 / 光标颜色</td><td><code>\\x1b]10;#ff0000\\x1b\\\\</code></td></tr><tr><td><code>52</code></td><td>设置 / 清空剪贴板（查询请求被忽略）</td><td>—</td></tr><tr><td><code>104</code></td><td>重置调色板为默认值</td><td>—</td></tr><tr><td><code>133</code></td><td>FinalTerm 语义转义（提示符 / 输入 / 输出区）</td><td>见 Shell Integration</td></tr><tr><td><code>777</code></td><td>rxvt 扩展，仅支持 <code>notify</code>（toast 通知）</td><td><code>printf &quot;\\e]777;notify;%s;%s\\e\\\\&quot; &quot;title&quot; &quot;body&quot;</code></td></tr><tr><td><code>1337</code></td><td>iTerm2 协议（内联图片等）</td><td>见 <a href="https://wezterm.org/imgcat.html" target="_blank" rel="noreferrer">iTerm Image Protocol</a></td></tr></tbody></table><p><code>3</code>（X11 窗口属性）、<code>5</code>、<code>6</code> 被 WezTerm 忽略。</p><p>示例（Bash：分别设置窗口标题与标签标题）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;\\033]2;my-window\\033\\\\&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 窗口标题</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;\\033]1;my-tab\\033\\\\&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 标签标题（图标名）</span></span></code></pre></div><h3 id="csi-控制序列" tabindex="-1">CSI：控制序列 <a class="header-anchor" href="#csi-控制序列" aria-label="Permalink to &quot;CSI：控制序列&quot;">​</a></h3><p>以 <code>ESC [</code> 引入，覆盖光标运动、擦除、模式开关、SGR 外观等。日常最常见的是 <strong>SGR</strong>（以 <code>m</code> 结尾），例如加粗、下划线、256 色 / TrueColor。</p><h3 id="备用屏幕与鼠标" tabindex="-1">备用屏幕与鼠标 <a class="header-anchor" href="#备用屏幕与鼠标" aria-label="Permalink to &quot;备用屏幕与鼠标&quot;">​</a></h3><p>全屏 TUI 常通过模式切换进入 <strong>alternate screen</strong>，并开启 <strong>鼠标跟踪</strong>。结果是：</p><ul><li>应用绘制在备用屏幕上，主屏幕回滚不一定累积 TUI 内部视图；</li><li>滚轮可能作为鼠标事件发给应用。</li></ul><p>因此会出现「在 Claude Code / 其它 TUI 里滚轮不滚动终端历史」的现象。处理思路见 <a href="./keys-scroll#tui--claude-code鼠标上报与终端滚动">快捷键与滚动</a> 与 <a href="./faq">FAQ</a>。</p><h2 id="对普通用户的建议" tabindex="-1">对普通用户的建议 <a class="header-anchor" href="#对普通用户的建议" aria-label="Permalink to &quot;对普通用户的建议&quot;">​</a></h2><ol><li>改标题、目录集成：优先用 shell 主题 / 官方 Shell Integration，而不是手写复杂 OSC。</li><li>调试「谁改了颜色 / 标题」：怀疑程序发出了 OSC 10/11/0/1/2。</li><li>需要精确协议行为：直接查阅官方 Escape Sequences 长文，并对照版本发行说明。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./faq">常见问题 FAQ</a></li><li><a href="./references">参考链接</a></li></ul>`,23)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
